bitfield.description:
valid if MEM_ADDRESS_CONFIG is in range 0..7  (2 and 5 are not supporterd - 128B MMBLK mode)

      ADDR_CFG_0 : is_config_valid = 1'b1;
      ADDR_CFG_1 : is_config_valid = 1'b1;
      ADDR_CFG_2 : is_config_valid = 1'b0; //128B is not supported in Osprey
      ADDR_CFG_3 : is_config_valid = 1'b1;
      ADDR_CFG_4 : is_config_valid = 1'b1;
      ADDR_CFG_5 : is_config_valid = 1'b0;  //128B is not supported in Osprey
      ADDR_CFG_6 : is_config_valid = 1'b1;
      ADDR_CFG_7 : is_config_valid = 1'b1;

ALLOC            = 2'b00,
REALLOC          = 2'b01,
DEALLOC          = 2'b10;
